//! Interface between the compiler and the platform view backends.
//!
//! The JS logic layer is generated by `weft-ui-codegen-js` for every
//! platform; a [`Codegen`] backend only produces the view layer of one
//! platform. The compiler does not know which backends exist.

use std::fmt;
use std::str::FromStr;

use crate::ir::Program;
use crate::view::ViewLayout;

/// Target platform; the string form matches `WEFT_PLATFORM`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Platform {
    Web,
    Wechat,
    Ios,
    Macos,
    Android,
    Windows,
    Linux,
}

impl Platform {
    /// Every platform, in declaration order.
    pub const ALL: [Platform; 7] = [
        Platform::Web,
        Platform::Wechat,
        Platform::Ios,
        Platform::Macos,
        Platform::Android,
        Platform::Windows,
        Platform::Linux,
    ];

    /// Name used by `WEFT_PLATFORM` and the Vite environments.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Platform::Web => "web",
            Platform::Wechat => "wechat",
            Platform::Ios => "ios",
            Platform::Macos => "macos",
            Platform::Android => "android",
            Platform::Windows => "windows",
            Platform::Linux => "linux",
        }
    }
}

impl fmt::Display for Platform {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Error for a string that names no [`Platform`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsePlatformError(String);

impl fmt::Display for ParsePlatformError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let names: Vec<&str> = Platform::ALL.iter().map(|p| p.as_str()).collect();
        write!(
            f,
            "unknown platform `{}`, expected one of: {}",
            self.0,
            names.join(", ")
        )
    }
}

impl std::error::Error for ParsePlatformError {}

impl FromStr for Platform {
    type Err = ParsePlatformError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Platform::ALL
            .into_iter()
            .find(|p| p.as_str() == s)
            .ok_or_else(|| ParsePlatformError(s.to_owned()))
    }
}

/// Input of a [`Codegen`] backend.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub struct Context<'p> {
    /// Application-level program: every `.weft` file of the app.
    pub program: &'p Program,
    /// View protocol layout of the program; `None` for `web`, whose logic
    /// modules write the DOM directly.
    pub layout: Option<&'p ViewLayout>,
    pub platform: Platform,
}

impl<'p> Context<'p> {
    #[must_use]
    pub fn new(program: &'p Program, layout: Option<&'p ViewLayout>, platform: Platform) -> Self {
        Self {
            program,
            layout,
            platform,
        }
    }
}

/// Generates the view layer of one platform.
pub trait Codegen {
    fn generate(&self, cx: &Context<'_>) -> Vec<OutputFile>;
}

/// A generated file at a `/`-separated path relative to the platform's
/// generated directory (`apps/<platform>/weft/`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OutputFile {
    pub path: String,
    pub contents: String,
}
